class Inventory:
    """Stock of named items: name -> (quantity, unit_price)."""

    def __init__(self):
        self.items = {}

    def add_item(self, name, quantity, unit_price):
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        current, _ = self.items.get(name, (0, unit_price))
        self.items[name] = (current + quantity, unit_price)

    def remove_item(self, name, quantity):
        """Remove quantity; KeyError if unknown, ValueError if more than in stock;
        an item that reaches 0 disappears."""
        raise NotImplementedError
